import Foundation

// MARK: - RTT API Models

struct RTTSearchResponse: Codable {
    let query: RTTQuery?
    let services: [RTTServiceModel]?
    
    // Shim for the old location object
    var location: RTTLocation? {
        guard let q = query?.location else { return nil }
        return RTTLocation(name: q.description ?? "", crs: q.shortCodes?.first ?? "")
    }
}

struct RTTQuery: Codable {
    let location: RTTLocationNode?
}

struct RTTLocationNode: Codable {
    let description: String?
    let shortCodes: [String]?
}

struct RTTLocation: Codable {
    let name: String
    let crs: String
}

struct RTTServiceModel: Codable, Identifiable {
    var id: String { scheduleMetadata?.uniqueIdentity ?? UUID().uuidString }
    
    let temporalData: RTTTemporalData?
    let locationMetadata: RTTLocationMetadata?
    let scheduleMetadata: RTTScheduleMetadata?
    let origin: [RTTEndpoint]?
    let destination: [RTTEndpoint]?

    // Store user search intent
    var userSearchOriginCRS: String?
    var userSearchDestinationCRS: String?
    var userSearchDestinationArrivalTime: String?

    // Derived helpers matching the old API

    var originCRS: String { 
        if let short = origin?.first?.location?.shortCodes?.first { return short }
        let desc = origin?.first?.location?.description ?? ""
        return ukStations.first { $0.name.lowercased() == desc.lowercased() }?.crs ?? ""
    }
    var originName: String { origin?.first?.location?.description ?? "" }
    var destinationCRS: String { 
        if let short = destination?.first?.location?.shortCodes?.first { return short }
        let desc = destination?.first?.location?.description ?? ""
        return ukStations.first { $0.name.lowercased() == desc.lowercased() }?.crs ?? ""
    }
    var destinationName: String { destination?.first?.location?.description ?? "" }

    /// Scheduled departure in "HH:mm" format
    var scheduledDeparture: String {
        let departureTime = temporalData?.departure?.scheduleAdvertised
        let arrivalTime = temporalData?.arrival?.scheduleAdvertised
        return format(isoTime: departureTime ?? arrivalTime)
    }

    /// Realtime departure in "HH:mm" format (falls back to scheduled)
    var realtimeDeparture: String {
        if let time = temporalData?.departure?.realtimeActual { return format(isoTime: time) }
        if let time = temporalData?.departure?.realtimeForecast { return format(isoTime: time) }
        if let time = temporalData?.departure?.scheduleAdvertised { return format(isoTime: time) }
        if let time = temporalData?.arrival?.realtimeActual { return format(isoTime: time) }
        if let time = temporalData?.arrival?.realtimeForecast { return format(isoTime: time) }
        if let time = temporalData?.arrival?.scheduleAdvertised { return format(isoTime: time) }
        return "--:--"
    }

    /// Delay in minutes (positive = late)
    var delayMinutes: Int {
        let scheduledStr = temporalData?.departure?.scheduleAdvertised ?? temporalData?.arrival?.scheduleAdvertised
        
        let realtimeStr: String?
        if let actual = temporalData?.departure?.realtimeActual { realtimeStr = actual }
        else if let forecast = temporalData?.departure?.realtimeForecast { realtimeStr = forecast }
        else if let arrActual = temporalData?.arrival?.realtimeActual { realtimeStr = arrActual }
        else if let arrForecast = temporalData?.arrival?.realtimeForecast { realtimeStr = arrForecast }
        else { realtimeStr = nil }
        
        guard let scheduled = scheduledStr, let realtime = realtimeStr else { return 0 }
        
        let s = minutesSinceMidnight(isoTime: scheduled)
        let r = minutesSinceMidnight(isoTime: realtime)
        return max(0, r - s)
    }

    var isCancelledService: Bool {
        temporalData?.departure?.isCancelled == true || temporalData?.arrival?.isCancelled == true
    }

    var trainStatus: TrainStatus {
        if isCancelledService { return .cancelled }
        if delayMinutes > 0   { return .delayed }
        return .onTime
    }

    var platform: String { locationMetadata?.platform?.actual ?? locationMetadata?.platform?.planned ?? "–" }
    
    var atocName: String? { scheduleMetadata?.operatorName?.name }

    // MARK: - Helpers

    private func format(isoTime: String?) -> String {
        guard let t = isoTime, t.count >= 19 else { return "--:--" }
        // "2026-08-02T18:12:00"
        let timePart = t.split(separator: "T").last ?? ""
        if timePart.count >= 5 {
            return String(timePart.prefix(5)) // HH:mm
        }
        return "--:--"
    }

    private func minutesSinceMidnight(isoTime: String) -> Int {
        let t = format(isoTime: isoTime)
        guard t.count == 5,
              let h = Int(t.prefix(2)),
              let m = Int(t.suffix(2)) else { return 0 }
        return h * 60 + m
    }
}

struct RTTTemporalData: Codable {
    let arrival: RTTTimeNode?
    let departure: RTTTimeNode?
}

struct RTTTimeNode: Codable {
    let scheduleAdvertised: String?
    let realtimeForecast: String?
    let realtimeActual: String?
    let isCancelled: Bool?
}

struct RTTLocationMetadata: Codable {
    let platform: RTTPlatformNode?
}

struct RTTPlatformNode: Codable {
    let planned: String?
    let actual: String?
}

struct RTTScheduleMetadata: Codable {
    let uniqueIdentity: String?
    let operatorName: RTTOperator?
    
    enum CodingKeys: String, CodingKey {
        case uniqueIdentity
        case operatorName = "operator"
    }
}

struct RTTOperator: Codable {
    let name: String?
}

struct RTTEndpoint: Codable {
    let location: RTTLocationNode?
    let temporalData: RTTTimeNode?
}

/// Typealias used in views — avoids repeating the long type name.
typealias RTTAPIService = RTTServiceModel

// MARK: - Station Data

import CoreLocation

/// Model representing a UK Railway Station for search autocomplete
struct UKStation: Identifiable, Hashable, Codable {
    var id: String { crs }
    let name: String
    let crs: String
    let lat: Double
    let lon: Double

    var coordinate: CLLocationCoordinate2D {
        CLLocationCoordinate2D(latitude: lat, longitude: lon)
    }

    // Enable easy hashing for SwiftUI ForEach and Picker
    static func == (lhs: UKStation, rhs: UKStation) -> Bool {
        lhs.crs == rhs.crs
    }

    func hash(into hasher: inout Hasher) {
        hasher.combine(crs)
    }
}

